# Writes src/scenes.json for "Live For Yourself, Not For Others", about 20 minutes. One narration clip per sentence.
# Reference: "Live For Yourself, Not For Others" (Let's Talk Psychology Podcast), a reading of the ideas in
# The Courage to Be Disliked (Kishimi and Koga) and Alfred Adler. Here the same ideas are told in new words, with
# stories from history, in the style of "How to Make Your Dream a Reality".
# Per sentence: th = picture themes (src/images.json), big = the key word (a script accent, or huge red capitals when
# red), gap = silence after.
import json
S = []
def s(text, th, big=None, red=False, gap=1.0):
    S.append(dict(id=f"s{len([x for x in S if 'text' in x]) + 1:03d}", text=text, th=th if isinstance(th, list) else [th], big=big, red=red, gap=gap))
def ch(num, title, dur=4.4): S.append(dict(id=f"ch{sum(1 for x in S if 'card' in x) + 1}", card="chapter", num=num, title=title, len=dur))

# ---- opening
s("Nearly two thousand years ago, the most powerful man in the world sat alone in a tent on the frontier of his empire and wrote a note to himself.", ["marcus"], big="alone")
s("I have often wondered, he wrote, how it is that every man loves himself more than all the rest of men, and yet sets less value on his own opinion of himself than on the opinion of others.", ["marcus"], big="opinion", red=True, gap=0.9)
s("The man was Marcus Aurelius, emperor of Rome.", ["marcus"], big="Marcus")
s("He commanded armies. He could end a life with a word.", ["marcus", "crowd"])
s("And still, at night, he caught himself wondering what other people thought of him.", ["night", "marcus"], big="wondering", gap=0.8)
s("If an emperor could not escape it, it is no surprise that we cannot.", ["face"])
s("We check how the photo was received. We replay the conversation on the drive home.", ["face", "night"])
s("We choose the job our parents can be proud of, the clothes that will not be laughed at, the opinions that will not cause trouble.", ["crowd", "face"], big="proud")
s("And slowly, without ever deciding to, we begin to live a life that is shaped by other people's eyes.", ["crowd"], big="eyes", red=True, gap=0.8)
s("This video is about how to stop.", ["face"], gap=0.3)
s("It is about an idea from a Viennese doctor named Alfred Adler, made famous again by a small Japanese book with a strange title.", ["adler"], big="Adler")
s("The Courage to Be Disliked.", ["adler", "face"], big="Disliked", red=True, gap=0.8)
s("It is not a book about becoming rude, or cold, or careless of other people.", ["face"])
s("It is about something much harder.", ["face"], gap=0.3)
s("Living your own life, while other people are watching.", ["alone", "crowd"], big="own", gap=1.0)

# ---- I
ch("I", "The invisible audience")
s("Think about the first years of your life.", ["child"], gap=0.3)
s("You took your first step, and the whole room clapped.", ["child"], big="clapped")
s("You brought home a good mark, and you were praised. You broke a plate, and you were scolded.", ["child", "school"])
s("Long before you could think for yourself, you had learned a simple rule.", ["child", "school"], big="rule")
s("Good is whatever earns approval. Bad is whatever earns punishment.", ["school"], big="approval", red=True)
s("Adler believed that this kind of upbringing, built on reward and punishment, quietly teaches a child to need an audience.", ["adler", "school"], big="audience")
s("The child does not ask, is this right? The child asks, will someone see it, and will they be pleased?", ["child"], gap=0.7)
s("Then the child grows up, and the audience grows with him.", ["crowd"], gap=0.3)
s("First it is parents and teachers. Then friends, and colleagues, and a boss.", ["crowd", "school"])
s("Then strangers on a screen, whose faces we will never see.", ["crowd", "night"], big="strangers")
s("We carry them everywhere, an invisible audience, watching every move and keeping score.", ["crowd", "theatre"], big="invisible", red=True)
s("And because we never chose them, we rarely notice how much of our life they are deciding.", ["face"], gap=0.7)
s("Most people would say that wanting approval is simply human.", ["face"])
s("Of course we want to be liked. We are social animals.", ["crowd"])
s("Adler agreed that we belong to one another. That was the centre of his whole philosophy.", ["adler"], big="belong")
s("But he drew a sharp line between belonging and being approved of.", ["adler"], big="line")
s("Belonging is knowing you have a place among people.", ["feast", "crowd"])
s("Approval is a wage they pay you for behaving as they wish.", ["crowd", "theatre"], big="wage")
s("And the trouble with a wage is that it can always be withdrawn.", ["face"], gap=1.0)

# ---- II
ch("II", "Goals, not causes")
s("Alfred Adler was born near Vienna in 1870. He was a sickly child, he nearly died of pneumonia, and he grew up in the shadow of a gifted older brother.", ["adler", "child"], big="Vienna")
s("He became a doctor, and in 1902 he was invited to join a small circle of thinkers that met every Wednesday in the apartment of Sigmund Freud.", ["freud", "adler"], big="Freud")
s("For nine years he sat in that circle. And then he walked out of it.", ["adler"], big="walked")
s("Freud believed that we are driven by our past. That the wounds of childhood push us, like a machine, into the people we become.", ["freud", "storm"], big="past")
s("Adler came to believe the opposite.", ["adler"], big="opposite", red=True, gap=0.5)
s("We are not pushed by causes, he said. We are pulled by goals.", ["adler", "morning"], big="goals")
s("Everything we think, feel and do is aimed at something, even when we are not aware of what it is.", ["face"])
s("Imagine a young man who has a job interview on Monday.", ["face"], big="Monday")
s("All week he is so anxious that he cannot prepare. On the morning of the interview, his hands shake and his stomach turns, and he stays at home.", ["night", "face"], big="anxious")
s("The usual explanation is simple. He was too anxious to go.", ["face"])
s("Adler would turn it around. He did not stay home because he was anxious. He became anxious, so that he could stay home.", ["adler", "face"], big="anxious", red=True)
s("His real goal was never the job. It was to avoid the risk of being judged and found lacking.", ["face", "crowd"], big="judged")
s("And fear was the perfect tool for it. It gave him a reason no one could argue with.", ["night"], gap=0.8)
s("This sounds harsh. It can feel like blaming a person for his own pain.", ["face"])
s("But Adler was not interested in blame. He was interested in freedom.", ["adler", "morning"], big="freedom")
s("If you are only the product of your past, you are stuck. Nobody can go back and change what happened to them.", ["storm"], big="stuck")
s("But if you are moving toward a goal, you can choose a different goal.", ["morning"], big="choose", red=True)
s("Adler did not deny that terrible things happen to people.", ["storm"])
s("He simply noticed that two people can live through the same hardship, and one is crushed by it while the other is made by it.", ["storm", "face"], big="same")
s("What decides it is not the experience. It is the meaning we give the experience.", ["face"], big="meaning")
s("Whatever has happened in your life until now, it does not have to decide how you live from now on.", ["morning"], big="now", red=True)
s("That is the first piece of courage this philosophy asks for.", ["alone"], big="courage", gap=1.0)

# ---- III
ch("III", "The price of approval")
s("Now look at approval through Adler's eyes.", ["crowd"])
s("If our lives are pulled by goals, then the question is not why do I feel this way. The question is, what am I trying to achieve?", ["face"])
s("And for a great many people, the honest answer is this. I am trying to be seen as good by others.", ["crowd", "face"], big="seen", red=True)
s("It looks like an innocent goal. It may even look like a kind one.", ["feast"])
s("But follow it to the end, and you find that it costs three things.", ["face"], big="three", gap=0.7)
s("The first is your freedom.", ["alone"], big="freedom", red=True)
s("When you live for approval, you must measure every choice with someone else's ruler.", ["crowd", "school"], big="ruler")
s("Is this the right career? You do not ask yourself. You ask, will they think it is impressive?", ["crowd"])
s("Is this the right partner, the right house, the right thing to say? Will they approve?", ["crowd", "face"])
s("You may receive a great deal of praise that way. But each piece of it is a small chain.", ["crowd"], big="chain")
s("Because to keep being praised, you must keep being what they praised.", ["theatre"], gap=0.7)
s("The second thing it costs is the goal itself.", ["face"])
s("Because approval is not in your hands. It never was.", ["crowd"], big="hands")
s("You can be honest, generous, talented and kind, and someone will still not like you. Someone will like you for being funny and dislike you for being serious.", ["crowd", "face"])
s("You can twist yourself into a hundred shapes and never satisfy everyone.", ["theatre"], big="hundred")
s("And people who realise this often make a strange choice.", ["face"])
s("Instead of letting go of the need for approval, they give up trying to earn it, and hide behind the giving up.", ["night", "face"], big="hide")
s("I am not clever enough. I am not attractive enough. People like me never get anywhere.", ["night"], gap=0.4)
s("It feels like honesty. But it is the job interview again.", ["face"])
s("The belief that they are flawed protects them from the risk of trying and being rejected.", ["night"], big="flawed")
s("They have not escaped the audience. They have just stopped going on stage.", ["theatre"], big="stage", red=True, gap=0.8)
s("And the third thing it costs is the people around you.", ["crowd", "feast"])
s("If my worth depends on being seen as good, then every other person is a rival for the same small light.", ["race", "crowd"], big="rival")
s("When a friend succeeds, something in me shrinks. When a colleague is praised, I feel I have lost.", ["race", "face"], big="lost")
s("Life becomes a race, with a few winners and many losers, and I am always checking where I stand.", ["race"], big="race", red=True)
s("It even poisons kindness.", ["feast"], gap=0.3)
s("Imagine you throw a surprise party for a friend. You plan it for weeks.", ["feast"], big="party")
s("Then your birthday comes, and your friend does nothing at all.", ["face", "night"])
s("If you were giving in order to receive, you will feel cheated. The gift was never a gift. It was a loan.", ["feast", "face"], big="loan")
s("Kishimi and Koga put it simply. A person who is obsessed with recognition is really only thinking about himself.", ["writer", "face"], big="himself", gap=1.0)

# ---- IV
ch("IV", "Whose task is it?")
s("So how do you stop?", ["face"], gap=0.3)
s("Adler's answer begins with one plain question, which you can ask about almost any worry in your life.", ["adler"], big="question")
s("Whose task is this?", ["adler", "face"], big="task", red=True, gap=0.8)
s("There is an old saying. You can lead a horse to water, but you cannot make it drink.", ["horse"], big="horse")
s("Leading the horse is your task. Drinking is the horse's.", ["horse"], big="drinking")
s("Most of our suffering in relationships, Adler believed, comes from reaching into tasks that are not ours, or letting others reach into ours.", ["crowd", "face"], big="reaching")
s("Doing your work well is your task. Whether your boss notices is your boss's task.", ["work"], big="your")
s("Being kind to someone is your task. Whether they like you for it is theirs.", ["feast", "face"])
s("Choosing your path is your task. What your family, your friends, or the strangers online make of it, is theirs.", ["alone", "crowd"], big="path")
s("This is not a wall between you and other people. You can still care, still help, still listen.", ["feast", "help"])
s("It is only an honest map of where your power ends.", ["morning"], big="ends")
s("You cannot control what anyone thinks of you. You can only control how you live.", ["alone"], big="control", red=True)
s("And there is a strange relief in that.", ["morning"], gap=0.3)
s("Because the moment you hand back other people's tasks, you no longer have to carry them.", ["alone", "morning"], big="carry")
s("Their opinion is still there. It just no longer belongs to you.", ["face"], gap=1.0)

# ---- V
ch("V", "The salon of the refused")
s("Here is what that looks like in a real life.", ["salon"], gap=0.3)
s("In the nineteenth century, there was only one way to succeed as a painter in France. You had to be accepted by the Salon.", ["salon"], big="Salon")
s("It was the great official exhibition in Paris, judged by a jury of the Academy.", ["salon", "crowd"])
s("The jury decided what good painting was. Smooth surfaces. Gods and heroes. History and myth. Polished, perfect, approved.", ["salon", "academic"], big="approved")
s("A painter the Salon rejected could not sell his work. Collectors would not touch him. Critics would not write about him.", ["salon"], big="rejected")
s("In 1863, the jury turned away so many paintings that the Emperor allowed the rejected works to be shown in a separate hall.", ["salon", "manet"], big="1863")
s("It became known as the Salon of the Refused. And the crowds came to laugh.", ["manet", "crowd"], big="laugh", red=True)
s("One painting drew the most laughter of all, Le Dejeuner sur l'herbe, by Edouard Manet.", ["manet"], big="Manet")
s("Critics called it vulgar. People stood in front of it and jeered.", ["manet", "crowd"], big="jeered")
s("A group of younger painters was watching. Claude Monet. Pierre Auguste Renoir. Camille Pissarro. Edgar Degas.", ["monet", "impression"], big="Monet")
s("They painted in a way the Academy hated. Quick, broken brushstrokes. Ordinary people, railway stations, gardens, rivers. Light, instead of legends.", ["impression"], big="light")
s("Year after year, the Salon rejected them.", ["impression", "salon"])
s("They had a choice, and it was the same choice that every person who lives for approval eventually faces.", ["monet", "face"], big="choice")
s("They could paint what the jury wanted, and be accepted. Or they could paint what they saw, and be disliked.", ["impression", "salon"], big="disliked", red=True)
s("In 1874, they stopped waiting for permission.", ["monet"], big="permission")
s("They rented the old studio of a photographer in Paris and put on an exhibition of their own.", ["impression"])
s("Monet hung a small, misty picture of a harbour at dawn, and called it Impression, Sunrise.", ["impression", "monet"], big="Sunrise")
s("A critic named Louis Leroy went to see it and wrote a mocking review.", ["writer", "impression"])
s("He said that wallpaper in its first stage was more finished than that painting. And he called the whole group, with contempt, the Impressionists.", ["impression"], big="Impressionists")
s("They took the insult and made it their name.", ["monet"], big="name", red=True)
s("Notice what they did and did not do.", ["impression"], gap=0.3)
s("They did not stop caring about painting. They did not stop wanting people to see their work.", ["impression", "crowd"])
s("They simply understood whose task was whose.", ["monet"])
s("Painting honestly was their task. Whether the jury approved, and whether the critics laughed, was not.", ["impression", "salon"], big="honestly")
s("Today the paintings the Salon celebrated hang in storerooms, and most of their names are forgotten.", ["salon", "academic"], big="forgotten")
s("And people cross the world, and stand in line for hours, to look at the light the Impressionists were laughed at for painting.", ["impression", "crowd"], big="light", gap=1.0)
s("There is an older story with the same lesson.", ["diogenes"], gap=0.3)
s("When Alexander the Great was the master of Greece, he went to visit the philosopher Diogenes, who owned almost nothing and lived in the street.", ["diogenes", "alexander"], big="Diogenes")
s("Alexander stood over him and asked if there was anything he could do for him.", ["alexander"], big="anything")
s("Diogenes looked up and said, yes. Stand a little out of my sun.", ["diogenes"], big="sun", red=True)
s("The most powerful man in the world could offer him nothing he needed.", ["diogenes", "alexander"])
s("And the story goes that as Alexander walked away, he said that if he were not Alexander, he would wish to be Diogenes.", ["alexander"], gap=1.0)

# ---- VI
ch("VI", "Of use to someone")
s("But there is a danger in everything we have said so far.", ["face"], big="danger")
s("If you stop living for other people's approval, do you simply stop caring about other people?", ["alone", "crowd"])
s("Adler's answer was no. In fact, it was the opposite.", ["adler"], big="opposite")
s("The final step of his philosophy was something he called community feeling. The sense that you belong to the people around you, and that you have something to give them.", ["adler", "feast"], big="community", red=True)
s("The person who lives for approval asks, what will they think of me?", ["crowd", "face"])
s("The person with community feeling asks, what can I contribute?", ["help", "work"], big="contribute")
s("Those two questions can lead to exactly the same action. Cooking a meal. Helping a colleague. Making a piece of work.", ["work", "feast", "help"])
s("But one of them makes you anxious, and the other makes you free.", ["morning"], big="free")
s("Because when you act to be recognised, you need a reward to know you did well.", ["crowd"])
s("When you act to contribute, you already know. You can feel, quietly, that you are of use to someone.", ["help", "work"], big="use", red=True)
s("And that feeling does not need anyone's applause to be real.", ["alone", "morning"], gap=0.8)
s("Kishimi and Koga go even further. They say that you do not have to do anything remarkable to be of value.", ["writer"], big="value")
s("Think of a newborn baby. It cannot work or win or impress anyone. And yet its mere existence fills a home with joy.", ["child", "mother"], big="existence")
s("Think of someone you love who is old or sick. You do not love them for what they achieve. You are glad, simply, that they are here.", ["mother", "face"], big="here")
s("If that is true of them, it is true of you.", ["face"], gap=0.3)
s("You do not have to earn your place in the world by being liked. You already have one.", ["morning", "alone"], big="place", red=True)
s("And when you know that, other people's success stops being a threat.", ["crowd", "race"])
s("Their light does not make yours any smaller. You can celebrate them, because you are no longer competing with them.", ["feast", "crowd"], big="celebrate", gap=1.0)

# ---- VII
ch("VII", "The courage to be disliked")
s("Here, at last, is the hard part.", ["face"], gap=0.3)
s("If you live this way, some people will not like you.", ["crowd"], big="some")
s("Not because you are cruel, or selfish, or wrong. But because you have stopped bending yourself into the shape of their expectations.", ["theatre", "alone"], big="bending")
s("Someone will call you arrogant. Someone will say you have changed. Someone will be disappointed in the choice you made.", ["crowd", "face"])
s("Adler's message, and the message of that small Japanese book, is that this is not a sign that something has gone wrong.", ["adler", "writer"])
s("It is the price of freedom. And it is a price worth paying.", ["alone", "morning"], big="price", red=True)
s("In the spring of 399 before Christ, the philosopher Socrates stood trial in Athens for corrupting the young.", ["socrates"], big="Socrates")
s("He could have begged. He could have brought his weeping children before the jury, as other men did, to win their pity.", ["socrates", "crowd"], big="begged")
s("He refused. He told the jury he would rather die having spoken in his own way than live by speaking in theirs.", ["socrates"], big="refused")
s("They sentenced him to death. And he drank the hemlock calmly, talking with his friends until the end.", ["socrates"], big="calmly")
s("Most of us will never face a jury like that.", ["face"], gap=0.3)
s("Our trials are smaller. A raised eyebrow at dinner. A message left on read. A parent's silence.", ["face", "feast", "night"], big="smaller")
s("But the choice is the same choice Socrates made, and the Impressionists made, and Diogenes made in the street.", ["socrates", "impression", "diogenes"])
s("Will I live by their measure, or by my own?", ["alone"], big="own", red=True, gap=1.0)
s("Adler had one more piece of advice, and it may be the most freeing of all.", ["adler"])
s("Stop living your life as if it were a line that only matters at the end.", ["race", "morning"], big="line")
s("When life is a climb toward a distant summit of approval and success, every day you have not reached it feels wasted.", ["storm", "alone"], big="wasted")
s("Kishimi and Koga suggest you live it instead like a dance.", ["feast", "morning"], big="dance")
s("A dance is not trying to get anywhere. Every moment of it is already complete.", ["feast", "morning"], big="complete")
s("If your life ended in the middle of the dance, it would not have been wasted. You were dancing.", ["morning", "alone"], big="dancing", red=True, gap=1.0)

# ---- close
s("Marcus Aurelius never fully freed himself from the opinions of others. Most of us won't either.", ["marcus"], big="never")
s("But he left himself a reminder in that same notebook.", ["marcus", "night"], gap=0.3)
s("How much trouble he avoids, he wrote, who does not look to see what his neighbour says or does, but only to what he does himself.", ["marcus"], big="himself")
s("Live like that.", ["alone", "morning"], big="Live", red=True, gap=0.5)
s("Do your own task, and hand back theirs.", ["work", "alone"], big="task")
s("Give, without keeping score.", ["help", "feast"], big="Give")
s("Know that you are already of use, already enough, already here.", ["morning", "mother"], big="enough")
s("And when someone does not like the life you have chosen, let them.", ["crowd", "alone"], big="let", gap=0.8)
s("It is their task.", ["face"], gap=0.4)
s("Your life is yours.", ["morning", "alone"], big="yours", red=True, gap=2.0)
json.dump(dict(voice="bm_george", speed=0.97, scenes=S), open("src/scenes.json", "w"), indent=1)
print(len([x for x in S if "text" in x]), "sentences,", sum(len(x["text"].split()) for x in S if "text" in x), "words")
